    public async Task<TaxProfileDto> CreatePartyAsync(Guid tenant, Guid actor, Guid correlation, TaxPartyProfileRequest request, CancellationToken ct, Guid? previousId = null)
    {
        if (request.CountryCode.Length != 2 || request.CountryCode.Any(c => !char.IsAsciiLetterUpper(c)) || request.EffectiveFrom == default || request.SchemeCode is { } partyScheme && (partyScheme.Length>40||partyScheme.Any(c=>!char.IsAsciiLetterUpper(c)&&!char.IsAsciiDigit(c)&&c!='_'))) throw new TaxException("tax.profile_invalid", "Party Tax Profile country, scheme, or effective date is invalid.");
        if(request.Treatment is { } treatment&&!Enum.TryParse<TaxTreatment>(treatment,true,out _))throw new TaxException("tax.treatment_invalid","Party Tax Treatment is not supported.");
        if(request.RegistrationStatus is { } registrationStatus&&!Enum.TryParse<TaxRegistrationStatus>(registrationStatus,true,out _))throw new TaxException("tax.registration_status_invalid","Party Registration Status is not supported.");
        if(request.RegistrationCountryCode is { } registrationCountry&&(registrationCountry.Length!=2||registrationCountry.Any(c=>!char.IsAsciiLetterUpper(c))))throw new TaxException("tax.country_code_invalid","Registration Country must be a two-letter country code.");
        if (!await directory.IsActivePartyAsync(new(tenant),request.PartyId,request.LegalEntityId,ct)) throw new TaxException("tax.party_not_found", "The Party is not active for this Legal Entity.");
        if (request.CategoryId is { } category && !await CategoryExistsAsync(tenant,category,"Party",ct)) throw new TaxException("tax.category_not_found", "The Party Tax Category was not found.");
        var id=Guid.CreateVersion7();
        return await transactions.ExecuteAsync<TaxProfileDto>(new(tenant),async (context,token)=>
        {
            if(request.RegistrationId is { } registrationId){if(request.LegalEntityId is not { } registrationEntity||!await ScalarBoolAsync(context,"select exists(select 1 from foundation_tax.tax_registration r join foundation_tax.tax_registration_member m on m.tenant_id=r.tenant_id and m.registration_id=r.id where r.tenant_id=$1 and r.id=$2 and r.scheme_code=$3 and r.status<>'Deregistered' and r.effective_from<=$4 and (r.effective_to is null or r.effective_to>$4) and m.legal_entity_id=$5 and m.membership_status='Active' and m.effective_from<=$4 and (m.effective_to is null or m.effective_to>$4))",token,tenant,registrationId,request.SchemeCode??string.Empty,request.EffectiveFrom,registrationEntity))throw new TaxException("tax.registration_not_available","The selected Tax Registration is not active for this Legal Entity, Scheme, and effective date.");}
            var series=id;var version=1L;
            if(previousId is { } priorId){if(!await ScalarBoolAsync(context,"select exists(select 1 from foundation_tax.party_tax_profile where tenant_id=$1 and id=$2 and party_id=$3 and legal_entity_id is not distinct from $4 and country_code=$5 and scheme_code is not distinct from $6)",token,tenant,priorId,request.PartyId,(object?)request.LegalEntityId??DBNull.Value,request.CountryCode,(object?)request.SchemeCode??DBNull.Value))throw new TaxException("tax.profile_not_found","Previous Party Tax Profile was not found in this profile scope.");await using var prior=new NpgsqlCommand("select profile_series_id,version,effective_from from foundation_tax.party_tax_profile where tenant_id=$1 and id=$2 for update",context.Connection,context.Transaction);prior.Parameters.AddWithValue(tenant);prior.Parameters.AddWithValue(priorId);await using var priorReader=await prior.ExecuteReaderAsync(token);if(!await priorReader.ReadAsync(token))throw new TaxException("tax.profile_not_found","Previous Party Tax Profile was not found.");series=priorReader.GetGuid(0);version=priorReader.GetInt64(1)+1;var oldFrom=priorReader.GetFieldValue<DateOnly>(2);await priorReader.CloseAsync();if(request.EffectiveFrom<=oldFrom)throw new TaxException("tax.profile_effective_date_invalid","A profile version must start after the previous version.");await using var closePrior=new NpgsqlCommand("update foundation_tax.party_tax_profile set effective_to=$3 where tenant_id=$1 and id=$2 and (effective_to is null or effective_to>$3)",context.Connection,context.Transaction);closePrior.Parameters.AddWithValue(tenant);closePrior.Parameters.AddWithValue(priorId);closePrior.Parameters.AddWithValue(request.EffectiveFrom);if(await closePrior.ExecuteNonQueryAsync(token)!=1)throw new TaxException("tax.profile_effective_date_invalid","The previous profile period does not contain the requested change date.");}
            var overlap=await ScalarBoolAsync(context,"select exists(select 1 from foundation_tax.party_tax_profile where tenant_id=$1 and party_id=$2 and id<>$7 and legal_entity_id is not distinct from $3 and country_code=$4 and scheme_code is not distinct from $5 and daterange(effective_from,effective_to,'[)') && daterange($6,null,'[)'))",token,tenant,request.PartyId,(object?)request.LegalEntityId??DBNull.Value,request.CountryCode,(object?)request.SchemeCode??DBNull.Value,request.EffectiveFrom,previousId??Guid.Empty);
            if(overlap)throw new TaxException("tax.profile_overlap","An effective Party Tax Profile already exists for this scope and date.");
