            await using var command=new NpgsqlCommand(sql,context.Connection,context.Transaction); command.Parameters.AddWithValue(tenant);command.Parameters.AddWithValue(id);command.Parameters.AddWithValue(series);command.Parameters.AddWithValue((object?)previousId??DBNull.Value);command.Parameters.AddWithValue(request.PartyId);command.Parameters.AddWithValue((object?)request.LegalEntityId??DBNull.Value);command.Parameters.AddWithValue((object?)request.RegistrationId??DBNull.Value);command.Parameters.AddWithValue(request.CountryCode);command.Parameters.AddWithValue((object?)request.SchemeCode??DBNull.Value);command.Parameters.AddWithValue((object?)request.CategoryId??DBNull.Value);command.Parameters.AddWithValue((object?)request.Treatment??DBNull.Value);command.Parameters.AddWithValue((object?)request.RegistrationNumber??DBNull.Value);command.Parameters.AddWithValue((object?)request.RegistrationCountryCode??DBNull.Value);command.Parameters.AddWithValue((object?)request.RegistrationStatus??DBNull.Value);command.Parameters.AddWithValue(request.ReverseChargeEligible);command.Parameters.AddWithValue((object?)request.EvidenceReference??DBNull.Value);command.Parameters.AddWithValue(request.EffectiveFrom);command.Parameters.AddWithValue(version);await command.ExecuteNonQueryAsync(token);
