            await AuditAsync(context,tenant,actor,correlation,"PartyTaxProfileChanged","PartyTaxProfile",id,request.LegalEntityId,dto,token); context.AddOutbox(new(Guid.CreateVersion7(),"PartyTaxProfileChangedV1",JsonSerializer.Serialize(new { id,request.PartyId,request.LegalEntityId,request.EffectiveFrom }),new(tenant),DateTimeOffset.UtcNow,correlation,id,"tax"));return dto;
