    public async Task<TaxCoverageResult> GetCoverageAsync(Guid tenant, TaxCoverageRequest request, CancellationToken ct)
    {
        if (request.LegalEntityId == Guid.Empty || request.At == default || request.CountryCode.Length != 2 || request.CountryCode.Any(c => !char.IsAsciiLetterUpper(c)))
            throw new TaxException("tax.coverage_context_invalid", "A Legal Entity, effective date, and two-letter country code are required.");
        await using var connection = await dataSource.OpenConnectionAsync(ct);
        await using var transaction = await connection.BeginTransactionAsync(ct);
        await SetTenantAsync(connection, transaction, tenant, ct);
        async Task<string?> Text(string sql, params object[] values)
        {
            await using var command = new NpgsqlCommand(sql, connection, transaction);
            foreach (var value in values) command.Parameters.AddWithValue(value ?? DBNull.Value);
            return await command.ExecuteScalarAsync(ct) as string;
        }
        async Task<bool> Exists(string sql, params object[] values)
        {
            await using var command = new NpgsqlCommand(sql, connection, transaction);
            foreach (var value in values) command.Parameters.AddWithValue(value ?? DBNull.Value);
            return (bool)(await command.ExecuteScalarAsync(ct) ?? false);
        }
        var entity = request.LegalEntityId;
        var at = request.At;
        var scheme = (object?)request.SchemeCode ?? DBNull.Value;
        var capability = await Text("select capability from foundation_tax.tax_capability_state where tenant_id=$1 and legal_entity_id=$2 and effective_from<=$3 and (effective_to is null or effective_to>$3) order by effective_from desc limit 1", tenant, entity, at) ?? "Missing";
        var packStatus = await Text("select case when validation_status='Valid' and (source_kind='TestOnly' or review_status='Approved') then 'Available' else 'Incompatible' end from foundation_tax.tax_pack_activation where tenant_id=$1 and country_code=$2 and status in ('Active','Superseded') and effective_from<=$3 and (effective_to is null or effective_to>$3) order by effective_from desc,activated_at desc nulls last limit 1", tenant, request.CountryCode, at) ?? "Missing";
        var registration = await Text("select status from foundation_tax.tax_registration r join foundation_tax.tax_registration_member m on m.tenant_id=r.tenant_id and m.registration_id=r.id where r.tenant_id=$1 and m.legal_entity_id=$2 and r.country_code=$3 and ($4::text is null or r.scheme_code=$4) and r.effective_from<=$5 and (r.effective_to is null or r.effective_to>$5) and r.status<>'Deregistered' and m.effective_from<=$5 and (m.effective_to is null or m.effective_to>$5) and m.membership_status='Active' order by r.effective_from desc limit 1", tenant, entity, request.CountryCode, scheme, at);
        var registrationOutOfPeriod = registration is null && await Exists("select exists(select 1 from foundation_tax.tax_registration r join foundation_tax.tax_registration_member m on m.tenant_id=r.tenant_id and m.registration_id=r.id where r.tenant_id=$1 and m.legal_entity_id=$2 and r.country_code=$3 and ($4::text is null or r.scheme_code=$4) and r.status<>'Deregistered' and m.membership_status='Active')", tenant, entity, request.CountryCode, scheme);
        var policy = await Text("select rounding_strategy from foundation_tax.tax_policy where tenant_id=$1 and legal_entity_id=$2", tenant, entity) ?? "Missing";
        var rounding = policy == "Missing" ? "Missing" : await Exists("select exists(select 1 from foundation_tax.tax_policy where tenant_id=$1 and legal_entity_id=$2 and money_scale between 0 and 8)", tenant, entity) ? "Configured" : "Missing";
        var productCoverage = request.ProductTemplateId is null ? "NotRequested" : await Exists("select exists(select 1 from foundation_tax.product_tax_profile where tenant_id=$1 and product_template_id=$2 and (product_variant_id is null or product_variant_id is not distinct from $3) and (legal_entity_id is null or legal_entity_id=$4) and (country_code is null or country_code=$5) and (scheme_code is null or scheme_code is not distinct from $6) and effective_from<=$7 and (effective_to is null or effective_to>$7))", tenant, request.ProductTemplateId.Value, (object?)request.ProductVariantId ?? DBNull.Value, entity, request.CountryCode, scheme, at) ? "Covered" : await Exists("select exists(select 1 from foundation_tax.product_tax_profile where tenant_id=$1 and product_template_id=$2 and (product_variant_id is null or product_variant_id is not distinct from $3) and (legal_entity_id is null or legal_entity_id=$4) and (country_code is null or country_code=$5) and (scheme_code is null or scheme_code is not distinct from $6) and effective_to is not null and effective_to<=$7)", tenant, request.ProductTemplateId.Value, (object?)request.ProductVariantId ?? DBNull.Value, entity, request.CountryCode, scheme, at) ? "Expired" : "Missing";
        var partyReadiness = request.PartyId is null ? "NotRequested" : await Exists("select exists(select 1 from foundation_tax.party_tax_profile where tenant_id=$1 and party_id=$2 and (legal_entity_id is null or legal_entity_id=$3) and country_code=$4 and (scheme_code is null or scheme_code is not distinct from $5) and effective_from<=$6 and (effective_to is null or effective_to>$6))", tenant, request.PartyId.Value, entity, request.CountryCode, scheme, at) ? "Ready" : "Missing";
        Guid? activeRuleSetId;
        await using (var ruleSet = new NpgsqlCommand("select id from foundation_tax.tax_rule_set where tenant_id=$1 and (legal_entity_id is null or legal_entity_id=$2) and (country_code is null or country_code=$3) and (scheme_code is null or scheme_code is not distinct from $4) and status='Active' and effective_from<=$5 and (effective_to is null or effective_to>$5) order by (legal_entity_id is not null) desc,(scheme_code is not null) desc,effective_from desc limit 1", connection, transaction))
        { ruleSet.Parameters.AddWithValue(tenant); ruleSet.Parameters.AddWithValue(entity); ruleSet.Parameters.AddWithValue(request.CountryCode); ruleSet.Parameters.AddWithValue(scheme); ruleSet.Parameters.AddWithValue(at); var id = await ruleSet.ExecuteScalarAsync(ct); activeRuleSetId = id is Guid value ? value : null; }
        var hasRules = activeRuleSetId is not null;
        var conflict = hasRules && await TaxRuleConflictValidator.HasConflictsAsync(connection, transaction, tenant, activeRuleSetId!.Value, ct);
        var hasApplicableRule = false;
        if (hasRules)
        {
            var productCategory = request.ProductTemplateId is { } template ? await ReadCategoryAsync(connection, transaction, tenant, "product_tax_profile", "product_template_id", template, request.ProductVariantId, entity, request.CountryCode, request.SchemeCode, at, ct) : null;
            var partyCategory = request.PartyId is { } party ? await ReadCategoryAsync(connection, transaction, tenant, "party_tax_profile", "party_id", party, null, entity, request.CountryCode, request.SchemeCode, at, ct) : null;
            hasApplicableRule = await Exists("select exists(select 1 from foundation_tax.tax_rule r join foundation_tax.tax_rule_version v on v.tenant_id=r.tenant_id and v.id=r.rule_version_id where r.tenant_id=$1 and r.rule_set_id=$2 and r.tax_date_from<=$3 and (r.tax_date_to is null or r.tax_date_to>$3) and (r.product_category_id is null or r.product_category_id is not distinct from $4) and (r.party_category_id is null or r.party_category_id is not distinct from $5) and (r.direction is null or r.direction is not distinct from $6) and (r.document_kind is null or r.document_kind is not distinct from $7) and (r.transaction_type is null or r.transaction_type is not distinct from $8) and (r.jurisdiction_code is null or r.jurisdiction_code is not distinct from $9))", tenant, activeRuleSetId!.Value, at, productCategory ?? (object)DBNull.Value, partyCategory ?? (object)DBNull.Value, (object?)request.Direction ?? DBNull.Value, (object?)request.DocumentKind ?? DBNull.Value, (object?)request.TransactionType ?? DBNull.Value, (object?)request.JurisdictionCode ?? DBNull.Value);
        }
        var result = TaxCoverageService.Evaluate(new(entity, at, request.CountryCode, capability, packStatus, registration, registrationOutOfPeriod,
            policy, rounding, productCoverage, partyReadiness, hasRules, conflict, hasApplicableRule, request.ProductTemplateId, request.PartyId));
        await transaction.CommitAsync(ct);
        return result;
    }

    private static async Task<Guid?> ReadCategoryAsync(NpgsqlConnection connection,NpgsqlTransaction transaction,Guid tenant,string table,string identityColumn,Guid identity,Guid? variant,Guid entity,string country,string? scheme,DateOnly at,CancellationToken ct)
    {
        var variantFilter=table=="product_tax_profile"?"and product_variant_id is not distinct from $3":"";
        var entityIndex=table=="product_tax_profile"?4:3;var countryIndex=table=="product_tax_profile"?5:4;var schemeIndex=table=="product_tax_profile"?6:5;var dateIndex=table=="product_tax_profile"?7:6;
        var sql=$"select category_id from foundation_tax.{table} where tenant_id=$1 and {identityColumn}=$2 {variantFilter} and (legal_entity_id is null or legal_entity_id is not distinct from ${entityIndex}) and (country_code is null or country_code=${countryIndex}) and (scheme_code is null or scheme_code is not distinct from ${schemeIndex}) and effective_from<=${dateIndex} and (effective_to is null or effective_to>${dateIndex}) order by (legal_entity_id is not null) desc,(scheme_code is not null) desc,effective_from desc limit 1";
        await using var command=new NpgsqlCommand(sql,connection,transaction);command.Parameters.AddWithValue(tenant);command.Parameters.AddWithValue(identity);if(table=="product_tax_profile")command.Parameters.AddWithValue(variant??(object)DBNull.Value);command.Parameters.AddWithValue(entity);command.Parameters.AddWithValue(country);command.Parameters.AddWithValue((object?)scheme??DBNull.Value);command.Parameters.AddWithValue(at);var value=await command.ExecuteScalarAsync(ct);return value is Guid id?id:null;
    }

    private async Task<IReadOnlyList<TaxProfileDto>> HistoryByIdAsync(Guid tenant,string table,Guid id,CancellationToken ct)
    {
        await using var c=await dataSource.OpenConnectionAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await SetTenantAsync(c,tx,tenant,ct);await using var cmd=new NpgsqlCommand($"select profile_series_id from foundation_tax.{table} where tenant_id=$1 and id=$2",c,tx);cmd.Parameters.AddWithValue(tenant);cmd.Parameters.AddWithValue(id);var series=await cmd.ExecuteScalarAsync(ct);return series is Guid seriesId?await QueryAsync(tenant,table,"and profile_series_id=$2",ct,seriesId):[];
    }

    public async Task<TaxProfileDto> EndAsync(Guid tenant,Guid actor,Guid correlation,bool party,Guid id,DateOnly effectiveTo,CancellationToken ct)
    {
        var table=party?"party_tax_profile":"product_tax_profile"; var type=party?"PartyTaxProfile":"ProductTaxProfile";
        await transactions.ExecuteAsync<bool>(new(tenant),async(context,token)=>
        {
            await using var cmd=new NpgsqlCommand($"update foundation_tax.{table} set effective_to=$3,version=version+1 where tenant_id=$1 and id=$2 and effective_to is null and effective_from<$3 returning id",context.Connection,context.Transaction);cmd.Parameters.AddWithValue(tenant);cmd.Parameters.AddWithValue(id);cmd.Parameters.AddWithValue(effectiveTo);if(await cmd.ExecuteScalarAsync(token)is null)throw new TaxException("tax.profile_not_endable","Profile was not found or effective end date is invalid.");
            await AuditAsync(context,tenant,actor,correlation,type+"Ended",type,id,null,new{effectiveTo},token);context.AddOutbox(new(Guid.CreateVersion7(),party?"PartyTaxProfileChangedV1":"ProductTaxProfileChangedV1",JsonSerializer.Serialize(new{id,effectiveTo}),new(tenant),DateTimeOffset.UtcNow,correlation,id,"tax"));return true;
        },ct);
        var result=await QueryAsync(tenant,table,"and id=$2",ct,id);return result.Count==0?throw new TaxException("tax.profile_not_found","Profile was not found."):result[0];
    }

